import { z } from "zod";

import { findRepeats } from "#shared/text/titles";

/** The most palettes the gallery may have, a few kinds of coloring; raise it when needed. */
export const maxPalettes = 30;

/**
 * Every palette of the gallery, as the client sends it to replace them all: a saved palette left
 * out is deleted. The palettes come in any order: the site and the admin list them by title.
 */
export const galleryPalettesBodySchema = z
  .strictObject({
    palettes: z
      .array(
        z.strictObject({
          /** Generated by the client, so a palette keeps its id while it is renamed. */
          id: z.uuid(),
          title: z.string().trim().min(1).max(50),
        }),
      )
      .max(maxPalettes),
  })
  .superRefine(({ palettes }, context) => {
    for (const { field, index } of findRepeats(palettes)) {
      context.addIssue({
        code: "custom",
        message: field === "id" ? "Each id must appear once" : "Another palette has this title",
        path: ["palettes", index, field],
      });
    }
  });

/**
 * The palettes as stored in Firestore and as the API returns them, sorted by title. Only their
 * shape is checked: the rules above apply when the palettes are saved, so tightening a rule later
 * never makes the saved palettes unreadable. There are none until they are first saved.
 */
export const galleryPalettesSchema = z.object({
  palettes: z.array(z.object({ id: z.string(), title: z.string() })),
});

export type GalleryPalettes = z.infer<typeof galleryPalettesSchema>;
